'use strict';
const atlas=window.RETH_ATLAS,pack=window.RETH_PACK;
const areas=Object.fromEntries(atlas.areas.map(a=>[a.id,a]));
const fileIndex=new Map(atlas.files.map(f=>[f.path,f]));
const annotations=[...pack.steps,...pack.details];
const explained=new Set(annotations.map(s=>s.path));
const KEY='reth-atlas-'+atlas.commit.slice(0,12);
const $=id=>document.getElementById(id);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const format=n=>n.toLocaleString('en-US');
let saved={};try{saved=JSON.parse(localStorage.getItem(KEY)||'{}')}catch{}
let state={view:'map',area:null,topic:null,folder:'',query:'',status:'all',hideTests:false,page:0,opened:[],queue:[],...saved};
state.opened=Array.isArray(state.opened)?state.opened.filter(p=>fileIndex.has(p)):[];
state.queue=Array.isArray(state.queue)?state.queue.filter(q=>q&&fileIndex.has(q.path)&&typeof q.question==='string'):[];
state.view=['map','files','queue'].includes(state.view)?state.view:'map';
if(!areas[state.area])state.area=null;
if(!atlas.topics.some(t=>t.id===state.topic))state.topic=null;
let source={path:null,text:null,offset:0,selection:null,anchor:null},controller=null,toastTimer;
const cache=new Map();
const sourceURL=p=>'https://github.com/paradigmxyz/reth/blob/'+atlas.commit+'/'+p.split('/').map(encodeURIComponent).join('/');
const topic=()=>atlas.topics.find(t=>t.id===state.topic);
const topicGuide=t=>t.id==='boot'?{href:'startup.html',label:'起動から稼働までの資料を読む →',status:'● 起動の資料あり'}:{href:'zoom.html?area=rpc',label:'送信処理の位置づけから読む →',status:'● 6ステップの送信解説あり'};
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{toast('保存に失敗しました。ブラウザーの空き容量をご確認ください。')}}
function toast(message){$('atlas-toast').textContent=message;$('atlas-toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('atlas-toast').classList.remove('show'),2800)}
function filterFiles(){return atlas.files.filter(f=>(!state.area||f.area===state.area)&&(!topic()||topic().areas.includes(f.area))&&f.path.startsWith(state.folder)&&f.path.toLowerCase().includes(state.query.toLowerCase())&&(!state.hideTests||!f.test)&&(state.status==='all'||state.status==='explained'&&explained.has(f.path)||state.status==='opened'&&state.opened.includes(f.path)||state.status==='unseen'&&!state.opened.includes(f.path)||state.status==='queued'&&state.queue.some(q=>q.path===f.path)))}
function setView(view){state.view=view;state.page=0;render();save()}
function selectArea(id){location.href='zoom.html?area='+encodeURIComponent(id)}
function clearScope(){state.area=null;state.topic=null;state.folder='';state.page=0;render();save()}
function selectTopic(id){state.topic=id;state.area=null;state.folder='';state.page=0;state.view='map';render();save();$('topic-banner').scrollIntoView({behavior:'smooth',block:'nearest'})}
function render(){document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));for(const view of ['map','files','queue'])$(view+'-view').hidden=state.view!==view;
$('view-label').textContent={map:'リポジトリの全体像',files:'構造からコードを探す',queue:'次に読む範囲'}[state.view];$('scope-label').textContent=state.area?' / '+areas[state.area].name:'';$('page-title').textContent={map:'まず、全体の中で位置をつかむ。',files:'必要な範囲まで、段階的に絞る。',queue:'次に知りたいことを、失わない。'}[state.view];$('page-desc').textContent={map:'構成 → モジュールの役割 → 関数の処理段階 → 実コード、と一段ずつ詳しくします。',files:'全 Rust ファイルのパスを索引化。本文は開いたファイルだけ取得し、100行ずつ表示します。',queue:'問いとコードの範囲を組にして保存し、次の読解・解説の準備につなげます。'}[state.view];$('queue-count').textContent=state.queue.length;$('coverage').textContent=`${format(state.opened.length)} / ${format(atlas.totalRust)} ファイルを開いた`;$('coverage-bar').style.width=(100*state.opened.length/atlas.totalRust)+'%';
$('area-nav').innerHTML=atlas.areas.map(a=>`<button class="area-item ${state.area===a.id?'selected':''}" data-area="${a.id}" style="--area:${a.color}"><i></i>${a.name}<span>${format(a.count)}</span></button>`).join('');
$('topic-banner').hidden=!topic();if(topic()){$('topic-banner').innerHTML=`<strong>今回の問い：${esc(topic().title)}</strong><div><span>${esc(topic().scope)}</span>${topic().ready?`<a href="${topicGuide(topic()).href}">${topicGuide(topic()).label}</a>`:'<button id="topic-files">この問いの領域を詳しく見る →</button>'}<button id="clear-topic">× 解除</button></div>`;$('clear-topic').onclick=()=>{state.topic=null;render();save()};if($('topic-files'))$('topic-files').onclick=()=>{location.href='zoom.html?area='+({block:'engine',sync:'sync',boot:'node'}[state.topic]||'rpc')}}
if(state.view==='map')renderMap();if(state.view==='files')renderFiles();if(state.view==='queue')renderQueue();document.querySelectorAll('[data-area]').forEach(b=>b.onclick=()=>selectArea(b.dataset.area));}
function renderMap(){const routes=[['transaction','送信・候補構築',['rpc','pool','payload']],['block','ブロックの検証',['rpc','engine','execution','storage']],['sync','同期',['network','sync','execution','storage']]];$('relation-lanes').innerHTML=routes.map(([id,label,ids])=>`<button class="relation-lane ${state.topic===id?'active':''}" data-route="${id}"><b>${label}</b><span>${ids.map(a=>areas[a].name).join(' → ')}</span></button>`).join('')+'<div class="relation-caption">責務のつながりを示す模式図 · 呼び出し順の保証ではありません</div>';document.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>selectTopic(b.dataset.route));const groups=[['node','rpc','network'],['pool','engine','sync'],['payload','execution','storage'],['extension','foundation']];
$('domain-map').innerHTML=groups.map(group=>'<div class="domain-layer">'+group.map(id=>{const a=areas[id];const ready=atlas.files.filter(f=>f.area===id&&explained.has(f.path)).length;return `<button class="domain-card ${state.area===id?'selected':''} ${(topic()&&!topic().areas.includes(id)||state.area&&id!==state.area&&!areas[state.area].neighbors.includes(id))?'dimmed':''}" data-area="${id}" style="--area:${a.color}"><span class="domain-code">${a.en}</span><strong>${a.name}</strong><div class="domain-meta"><span>${format(a.count)} Rust files</span>${ready?`<span class="ready">${ready} files に送信経路の抜粋解説</span>`:'<span>送信経路の抜粋解説なし</span>'}</div><div class="domain-size"><i style="width:${Math.max(3,100*a.count/Math.max(...atlas.areas.map(x=>x.count)))}%"></i></div></button>`}).join('')+'</div>').join('');
const a=areas[state.area];
$('context-panel').innerHTML=a?`<div class="context-inner"><div class="eyebrow">AREA / ${a.en}</div><h2>${a.name}</h2><p>${a.description}</p><span class="label">この領域の問い</span><p>${a.question}</p><button id="browse-area" class="primary wide">${format(a.count)} ファイルの内側を見る →</button><span class="label">入口の候補 · 実ファイル</span>${a.entry.map(p=>`<button class="entry-btn" data-open="${p}">↗ ${p}</button>`).join('')}<span class="label">関連して読む領域 · 説明用の整理</span><div class="neighbor-list">${a.neighbors.map(id=>`<button data-area="${id}">${areas[id].name}</button>`).join('')}</div><span class="label">分類の根拠：ディレクトリ</span><div class="classification">${a.prefixes.length?a.prefixes.join('<br>'):'ほかの分類に含まれない全 Rust ファイル'}</div><p>${a.manifests} Cargo.toml · Rust ファイル数はテストを含む</p></div>`:`<div class="context-inner"><div class="eyebrow">YOU ARE HERE / REPOSITORY</div><h2>今見ているのは<br>コードの「地形」です。</h2><p>ノードを選ぶと、責務・入口のファイル・関連領域を表示します。規模が大きくても、最初にすべての関数は並べません。</p><span class="label">作成済みの読解範囲</span><p>トランザクション送信の ${explained.size} ファイル・${annotations.length} 抜粋に解説があります。起動から稼働までの流れは、起動資料で読めます。</p><a class="resume" href="startup.html" style="display:block;text-align:center">起動から稼働までの資料を読む →</a><a class="resume" href="zoom.html?area=rpc" style="display:block;text-align:center">RPC の内部構成から読む →</a><span class="label">地図の根拠を読む</span><a href="https://github.com/paradigmxyz/reth/blob/${atlas.commit}/AGENTS.md#architecture" target="_blank" rel="noopener">リポジトリの Architecture 記述 ↗</a><p>分類・関連領域は事前作成の案内です。正確な呼び出し関係は、コード側で確認します。</p></div>`;
if(a)$('browse-area').onclick=()=>setView('files');document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openFile(b.dataset.open));
$('topics').innerHTML=atlas.topics.map((t,i)=>`<button class="topic-card ${state.topic===t.id?'active':''}" data-topic="${t.id}"><div class="topic-num">QUESTION 0${i+1}</div><h3>${t.title}</h3><p>${t.desc}</p><span>${t.ready?topicGuide(t).status:'○ 読む入口の候補 · 解説未作成'} &nbsp; →</span></button>`).join('');document.querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>selectTopic(b.dataset.topic));}
function renderFiles(){const files=filterFiles();const pages=Math.max(1,Math.ceil(files.length/50));state.page=Math.min(state.page,pages-1);$('path-search').value=state.query;$('status-filter').value=state.status;$('hide-tests').checked=state.hideTests;$('file-total').textContent=`${format(files.length)} / ${format(atlas.totalRust)} Rust files`;
let crumbs='<button data-folder="">全体</button>';let cursor='';for(const part of state.folder.split('/').filter(Boolean)){cursor+=part+'/';crumbs+=` / <button data-folder="${cursor}">${esc(part)}</button>`}$('folder-breadcrumb').innerHTML=crumbs;
const dirs=new Map();for(const f of files){const remain=f.path.slice(state.folder.length);if(remain.includes('/')){const key=remain.split('/')[0]+'/';dirs.set(key,(dirs.get(key)||0)+1)}}
$('folders').innerHTML=[...dirs].sort((a,b)=>b[1]-a[1]).map(([dir,count])=>`<button class="folder" data-folder="${state.folder+dir}">▱ <b>${esc(dir)}</b><span>${format(count)}</span></button>`).join('');
$('file-results').innerHTML=files.slice(state.page*50,state.page*50+50).map(f=>`<button class="file-row" data-open="${f.path}"><span><b>◧ &nbsp;${esc(f.path.split('/').pop())}</b><small>${esc(f.path)}</small></span><span class="row-area">${areas[f.area].name}</span><span class="status-tag ${explained.has(f.path)?'explained':''}">${explained.has(f.path)?'● 送信経路の抜粋あり':state.queue.some(q=>q.path===f.path)?'◷ キューあり':state.opened.includes(f.path)?'◌ 開いた':'○ 未閲覧'}${state.opened.includes(f.path)&&explained.has(f.path)?'<br>開いたファイル':''}</span></button>`).join('')||'<div class="empty">この条件に一致するファイルはありません。検索語や絞り込みを変えてください。</div>';
$('page-label').textContent=`${state.page+1} / ${pages} ページ · 50件ずつ表示`;$('page-prev').disabled=state.page===0;$('page-next').disabled=state.page>=pages-1;document.querySelectorAll('[data-folder]').forEach(b=>b.onclick=()=>{state.folder=b.dataset.folder;state.page=0;renderFiles();save()});document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openFile(b.dataset.open));}
function renderQueue(){$('queue-list').innerHTML=state.queue.map((q,i)=>`<article class="queue-card"><span class="status-tag">未生成 · 読解対象を保存済み</span><h3>${esc(q.question)}</h3><p>${esc(q.path)} ${q.lines?`· L${q.lines[0]}–L${q.lines[1]}`:'· ファイル全体'} · ${atlas.commit.slice(0,12)}</p><button data-queue-open="${i}">コードを開く ↗</button><button data-queue-delete="${i}">キューから削除</button></article>`).join('')||'<div class="empty">キューはまだ空です。コードを開き、知りたいことを入力して追加できます。</div>';document.querySelectorAll('[data-queue-open]').forEach(b=>b.onclick=()=>{const q=state.queue[+b.dataset.queueOpen];openFile(q.path,q.lines)});document.querySelectorAll('[data-queue-delete]').forEach(b=>b.onclick=()=>{state.queue.splice(+b.dataset.queueDelete,1);render();save()});}
async function openFile(path,selection=null){if(!fileIndex.has(path))return;controller?.abort();controller=new AbortController();const ownController=controller;source={path,text:null,offset:selection?Math.floor((selection[0]-1)/100)*100:0,selection,anchor:selection?.[0]||null};const a=areas[fileIndex.get(path).area];$('source-area').textContent=`05 / 実コード / ${a.name}`;$('source-name').textContent=path.split('/').pop();$('source-path').textContent=path;$('github-file').href=sourceURL(path);$('source-role').textContent=a.question;$('source-description').textContent=a.description;$('source-status').textContent='コード本文を読み込み中…';$('source-lines').innerHTML='<div class="empty">固定コミットのコードを取得しています…</div>';$('reading-question').value='';$('goto-line').value=selection?.[0]||1;$('source-window').textContent='';$('lines-prev').disabled=true;$('lines-next').disabled=true;$('go-line').disabled=true;updateSelection();
const ready=annotations.filter(s=>s.path===path);$('available-explanations').innerHTML=ready.length?'<span class="label">このファイルの送信経路の解説範囲</span>'+ready.map(s=>`<a href="reader.html?step=${s.id}">${esc(s.title)} · L${s.start}–L${s.end} ↗</a>`).join(''):'<span class="indexed-chip">送信経路の抜粋解説なし</span><p>この画面の抜粋解説は送信経路が対象です。問いと範囲をキューに残せます。</p><a href="startup.html">起動から稼働までの資料を読む →</a>';
if(!$('source-dialog').open)$('source-dialog').showModal();
const timeout=setTimeout(()=>ownController.abort(),20000);
try{let text=atlas.seed[path]??cache.get(path);if(text===undefined){const response=await fetch('https://raw.githubusercontent.com/paradigmxyz/reth/'+atlas.commit+'/'+path.split('/').map(encodeURIComponent).join('/'),{signal:ownController.signal,credentials:'omit'});if(!response.ok)throw Error('HTTP '+response.status);if(Number(response.headers.get('content-length'))>2_000_000)throw Error('2MBを超えるファイル');text=await response.text();if(text.length>2_000_000)throw Error('2MBを超えるファイル');cache.set(path,text);while(cache.size>12)cache.delete(cache.keys().next().value)}if(source.path!==path||controller!==ownController)return;source.text=text;if(!state.opened.includes(path)){state.opened.push(path);save();render()}$('source-status').textContent=`実コード · ${atlas.commit.slice(0,12)} · ${atlas.seed[path]!==undefined?'同梱スナップショット':'必要時に取得'}`;$('go-line').disabled=false;renderSource();}catch(error){if(source.path!==path||controller!==ownController)return;$('source-status').textContent='本文の取得に失敗';$('source-lines').innerHTML=`<div class="source-failure">${esc(error.name==='AbortError'?'取得がタイムアウト、またはキャンセルされました。':error.message)}<br>公開GitHubへの接続やサイト側の通信制限で取得できない場合があります。<br><a href="${sourceURL(path)}" target="_blank" rel="noopener">GitHubで原文を開く ↗</a><p><button id="retry-source">再試行</button></p></div>`;$('retry-source').onclick=()=>openFile(path,selection)}finally{clearTimeout(timeout)}}
function updateSelection(){$('selected-scope').textContent=source.selection?`対象：L${source.selection[0]}–L${source.selection[1]}（Shift+クリックで範囲選択）`:'対象：ファイル全体 · 行を選ぶと範囲を限定できます';}
function renderSource(){if(source.text===null)return;const lines=source.text.split('\n');if(lines.at(-1)==='')lines.pop();source.offset=Math.max(0,Math.min(source.offset,Math.max(0,Math.floor((lines.length-1)/100)*100)));const end=Math.min(lines.length,source.offset+100);$('source-window').textContent=`L${source.offset+1}–L${end} / ${format(lines.length)} 行`;$('source-lines').innerHTML=lines.slice(source.offset,end).map((line,i)=>{const n=source.offset+i+1;return `<button class="atlas-code-row ${source.selection&&n>=source.selection[0]&&n<=source.selection[1]?'selected':''}" data-source-line="${n}"><span>${n}</span><code>${esc(line)||' '}</code></button>`}).join('');$('lines-prev').disabled=source.offset===0;$('lines-next').disabled=end>=lines.length;document.querySelectorAll('[data-source-line]').forEach(b=>b.onclick=e=>{const n=+b.dataset.sourceLine;if(e.shiftKey&&source.anchor){source.selection=[Math.min(source.anchor,n),Math.max(source.anchor,n)]}else{source.anchor=n;source.selection=[n,n]}renderSource();updateSelection()});}
function addQueue(){const question=$('reading-question').value.trim();if(!question){$('reading-question').focus();return}state.queue.push({path:source.path,lines:source.selection?[...source.selection]:null,question,commit:atlas.commit,createdAt:new Date().toISOString()});save();render();$('reading-question').value='';$('queue-add').textContent='✓ キューに追加しました';setTimeout(()=>$('queue-add').textContent='＋ 読解キューに追加',1800)}
$('commit-link').href='https://github.com/paradigmxyz/reth/commit/'+atlas.commit;$('commit-link').textContent=atlas.commit.slice(0,12)+' ↗';$('rust-count').textContent=format(atlas.totalRust);$('index-status').textContent=`Git tree: ${format(atlas.totalTracked)} tracked files / ${format(atlas.totalCargo)} Cargo.toml · ${atlas.commit.slice(0,12)}`;
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));$('reset').onclick=()=>{state.view='map';state.query='';state.status='all';clearScope()};$('clear-scope').onclick=clearScope;$('path-search').oninput=e=>{state.query=e.target.value;state.page=0;renderFiles();save()};$('status-filter').onchange=e=>{state.status=e.target.value;state.page=0;renderFiles();save()};$('hide-tests').onchange=e=>{state.hideTests=e.target.checked;state.page=0;renderFiles();save()};$('page-prev').onclick=()=>{state.page--;renderFiles();save()};$('page-next').onclick=()=>{state.page++;renderFiles();save()};$('close-source').onclick=()=>$('source-dialog').close();$('source-dialog').addEventListener('close',()=>controller?.abort());$('go-line').onclick=()=>{const n=Math.max(1,Number($('goto-line').value)||1);source.offset=Math.floor((n-1)/100)*100;renderSource()};$('lines-prev').onclick=()=>{source.offset-=100;renderSource();$('source-lines').scrollTop=0};$('lines-next').onclick=()=>{source.offset+=100;renderSource();$('source-lines').scrollTop=0};$('queue-add').onclick=addQueue;
$('export-queue').onclick=()=>{const blob=new Blob([JSON.stringify({schemaVersion:1,repository:'paradigmxyz/reth',commit:atlas.commit,aiStatus:'not-connected',queue:state.queue},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='reth-reading-queue.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
const params=new URLSearchParams(location.search);if(areas[params.get('area')]){state.area=params.get('area');state.view='map';state.topic=null;state.folder=''}
render();

const directFile=params.get('file');if(fileIndex.has(directFile)){const line=Math.max(1,Number(params.get('line'))||1);openFile(directFile,[line,line]);const from=params.get('from');if(from&&from.startsWith('zoom.html?')){$('source-description').insertAdjacentHTML('afterend','<a id="return-to-process">← 04 関数の説明へ戻る</a>');$('return-to-process').href=from;}}
